function productGalleryView(index){const kind=productSlides[index].kind;const headings={reflection:'How did your shift go?',passport:'Skill Passport.',mission:'Your next shift.',manager:'Ready for a closer look.'};const content={reflection:`<div class="tour-reflection"><div class="tour-mic" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.6"><rect x="12" y="4" width="8" height="15" rx="4"/><path d="M8 14v3a8 8 0 0 0 16 0v-3M16 25v4m-5 0h10"/></svg></div><h4>Your shift. In your own words.</h4><p>What did you do? Where did you need support?</p><div class="tour-quote">“I handled three orders independently, but needed help with a special request.”</div></div>`,passport:`<div class="tour-skill-grid">${[['Guest interaction','Learning record'],['Menu knowledge','Practising'],['Order taking','Evidence added'],['Special requests','Next focus']].map(([n,t])=>`<div><span class="tour-skill-icon">${n==='Menu knowledge'?'▤':'✧'}</span><b>${n}</b><small>${t}</small></div>`).join('')}</div>`,mission:`<div class="tour-mission"><span class="pill neutral">NEXT SHIFT / TO DO</span><h4>Confirm the details.<br>Build the habit.</h4><p>Repeat special requests back before confirming an order.</p></div><div class="tour-task"><span>01</span> Practise with supervisor support</div><div class="tour-task"><span>02</span> Record what happened afterwards</div>`,manager:`<div class="tour-review"><div class="tour-person"><span class="avatar">AC</span><div><b>Alex Chen</b><small>Shift record ready for review</small></div><span class="pill neutral">Pending</span></div><div class="tour-quote">“I handled three orders independently, but needed help with a special request.”</div><div class="tour-review-bottom"><span>Order taking</span><b>Review evidence →</b></div></div><div class="tour-task"><span>↗</span> See the experience behind the progress</div>`};const notes={reflection:['START WITH THE EXPERIENCE','Capture the moment.','A brief reflection gives the learning a starting point.'],passport:['KEEP THE EVIDENCE','See what’s building.','One place for experiences, learning steps and review status.'],mission:['MAKE IT PRACTICAL','Go in with a focus.','A clear task connects today’s learning to tomorrow’s work.'],manager:['KEEP PEOPLE CONNECTED','Coach with context.','Review the record and use human judgement to confirm progress.']};return `<div class="tour-stage"><div class="tour-window"><div class="tour-chrome"><span><i></i><i></i><i></i></span><p>ALT / ${kind==='manager'?'Manager workspace':'Employee workspace'}</p><small>Product tour</small></div><div class="tour-brandbar"><img src="assets/alt-mark-dark.svg" alt="ALT"><span>LEARNING, MADE VISIBLE.</span><b>✧</b></div><div class="tour-layout"><aside class="tour-sidebar"><span class="${kind==='reflection'?'active':''}">Today</span><span class="${kind==='passport'?'active':''}">Passport</span><span class="${kind==='mission'?'active':''}">Next shift</span><span class="${kind==='manager'?'active':''}">Manager</span></aside><div class="tour-workspace"><p class="eyebrow">${kind==='manager'?'YOUR TEAM. THEIR PROGRESS.':'YOUR GROWTH. YOUR PROOF.'}</p><h3>${headings[kind]}</h3>${content[kind]}</div><aside class="tour-insight"><p class="eyebrow">${notes[kind][0]}</p><h4>${notes[kind][1]}</h4><p>${notes[kind][2]}</p><div class="tour-identity"><span class="avatar">AC</span><div>Alex Chen<small>Demonstration profile</small></div></div></aside></div></div></div>`;}
