function setAudience(role){
 const stories={
 employee:{label:'AFTER SERVICE / EMPLOYEE VIEW',title:'Leave with a plan, not a lingering doubt.',copy:'Alex missed a special request. ALT turns the reflection into one practical focus for tomorrow.',points:['A mistake becomes something to work on','The next shift starts with a clear focus'],panel:`<p class="eyebrow">ILLUSTRATIVE SCENARIO / ALEX</p><h3>From “I got it wrong”<br>to “I know what to try”.</h3><div class="evidence-note">“I took the order independently, but missed the no-onion request. My supervisor helped me correct it.”</div><div class="status-row"><span>Order taking</span><span class="pill neutral">Awaiting review</span></div><div class="phone-mission" style="font-size:15px;padding:24px"><b style="font-size:10px">PROPOSED NEXT STEP</b>Repeat special requests back before confirming an order.</div>`},
 manager:{label:'BEFORE THE NEXT SHIFT / MANAGER VIEW',title:'Make a limited coaching moment count.',copy:'The manager sees the support Alex needs. Their next check-in starts with a clear focus.',points:['See the reason behind a support need','Give feedback on a concrete experience'],panel:`<p class="eyebrow">ILLUSTRATIVE SCENARIO / MANAGER</p><h3>A clearer coaching conversation.</h3><div class="mini-person"><span class="avatar">AC</span><div>Alex Chen<small>Special requests · Review requested</small></div></div><div class="evidence-note" style="margin-top:24px">Practice focus: ask Alex to repeat the guest’s special request back during a supported order.</div><div class="status-row"><span>Next-shift support</span><span class="pill">Supervisor check-in</span></div>`},
 next:{label:'BACK ON THE FLOOR / NEXT SHIFT',title:'Let a small improvement become visible.',copy:'Alex practises with a supervisor, then records what changed. Progress becomes visible to both of them.',points:['Keep useful learning beyond a single shift','Build towards independence through reviewed practice'],panel:`<p class="eyebrow">ILLUSTRATIVE SCENARIO / NEXT SHIFT</p><h3>Make the next attempt count.</h3><div class="phone-mission" style="font-size:20px;padding:28px"><b style="font-size:10px">TODAY’S PRACTICE</b>“A beef burger, no onion, and sparkling water. Is that right?”</div><div class="status-row"><span>After practice</span><span class="pill neutral">Add new evidence</span></div><p class="micro">Progress builds through repeated work and manager review.</p>`}
 };const story=stories[role];document.querySelectorAll('[data-audience]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.audience===role)));document.querySelector('#audience-copy').innerHTML=`<p class="eyebrow story-stage">${story.label}</p><h3 class="story-title">${story.title}</h3><p class="audience-copy">${story.copy}</p><a class="text-link" href="?page=demo">Follow the experience in the demo ↗</a><p class="micro story-disclosure">Illustrative scenario · Intended benefits shown; not measured customer outcomes.</p>`;document.querySelector('#audience-panel').innerHTML=`<div class="story-visual" aria-hidden="true"><div class="story-order">${tinyIcon('order')}<small>TABLE 04</small><b>Beef burger</b><span>No onion</span></div><span class="story-connector">→</span><div class="story-outcome">${tinyIcon(role==='employee'?'route':role==='manager'?'people':'seed')}<b>${role==='employee'?'One clear focus':role==='manager'?'A useful check-in':'A better next attempt'}</b><span>${role==='employee'?'Repeat the special request':role==='manager'?'Coach with the full picture':'Practise. Reflect. Build.'}</span></div></div>`+story.panel;
}
function team(){main.innerHTML=`<div class="container"><section class="team-intro visual-team-intro"><div><p class="eyebrow">THE PEOPLE BEHIND ALT</p><h1>A better start<br>begins with people.</h1><p>Three perspectives. One shared purpose:<br>make learning work on the floor.</p></div>${teamIllustration()}</section><section class="team-origin visual-origin"><div><p class="eyebrow">WHERE OUR PERSPECTIVES MEET</p><h2>Grounded in service.<br>Built around people.</h2><p>Hospitality, communication and Wine and Food Business come together in ALT—with clearer learning for staff and better context for managers.</p></div>${perspectiveVisual()}</section><section class="team-members"><div class="team-section-head"><p class="eyebrow">MEET ALT</p><h2>Align. Learn. Thrive.</h2></div><div class="public-team-list"><article><span class="alt-letter" aria-hidden="true">A</span><span class="alt-meaning">ALIGN</span><p class="alt-value">Start with a shared direction.</p><span class="member-index">LEARNING & PRODUCT EXPERIENCE</span><div class="member-name-row"><h3>Allison</h3><a class="member-social" href="https://www.linkedin.com/in/yuchen-jiang-8a365235b/" target="_blank" rel="noopener" aria-label="Allison on LinkedIn" title="Allison on LinkedIn">${linkedinIcon}</a></div><p class="member-public-bio">Allison brings a Wine and Food Business perspective to the Skill Passport, connecting everyday work with a clear learning journey.</p></article><article><span class="alt-letter" aria-hidden="true">L</span><span class="alt-meaning">LEARN</span><p class="alt-value">Turn experience into understanding.</p><span class="member-index">COMMUNICATION & CONTENT</span><div class="member-name-row"><h3>Loreley</h3><a class="member-social" href="https://www.linkedin.com/in/loreleylee/" target="_blank" rel="noopener" aria-label="Loreley on LinkedIn" title="Loreley on LinkedIn">${linkedinIcon}</a></div><p class="member-public-bio">Loreley brings over five years in communications and content to ALT’s product story, making its value and learning experience clear.</p></article><article><span class="alt-letter" aria-hidden="true">T</span><span class="alt-meaning">THRIVE</span><p class="alt-value">Build confidence through practice.</p><span class="member-index">HOSPITALITY & PEOPLE</span><div class="member-name-row"><h3>Tommy</h3><a class="member-social" href="https://www.linkedin.com/in/tommysun%E5%AD%AB%E9%9F%9C%E8%9E%8D/" target="_blank" rel="noopener" aria-label="Tommy on LinkedIn" title="Tommy on LinkedIn">${linkedinIcon}</a></div><p class="member-public-bio">A hospitality supervisor and sommelier, Tommy brings extensive hotel guest and team communication experience, grounding ALT in hands-on service and training.</p></article></div><p class="team-shared-line">Align expectations. Learn through experience. Thrive through practice.</p></section></div>`;}
function contact(){main.innerHTML=`<div class="container"><section class="team-intro"><p class="eyebrow">CONTACT ALT</p><h1>Let’s make the<br>next shift better.</h1><p>Share your experience, explore a pilot, or talk about working together.</p></section><section class="contact-page-panel"><div><p class="eyebrow">YOUR PERSPECTIVE MATTERS</p><h2>What would help<br>your team?</h2><p>Tell us what worked, what’s missing, or where ALT could fit in your workplace.</p><a class="btn" href="${formURL}" target="_blank" rel="noopener">Share feedback or get in touch ${arrow}</a><p class="micro">Opens our existing Google Form. Use the comments field for your message.</p></div><aside><p class="eyebrow">EMAIL THE TEAM</p><a class="contact-email" href="mailto:hello.alt.team@gmail.com">hello.alt.team@gmail.com</a><p>Prefer a direct conversation? Send us an email.</p></aside></section></div>`;}

let rounds=defaultRounds;
let introRefreshTimer;
let playerName='', boardToken='', gameAnswers=[], boardResult=null, boardError='', boardBusy=false;
const visitorName=()=>isStandalone?'Alex Chen':(playerName||'Guest');
const visitorInitials=()=>visitorName().split(/\s+/).map(w=>[...w][0]||'').slice(0,2).join('').toUpperCase();
let roundIndex=0, roundResults=[], order=rounds[0], rushSpeed=.95, phraseTimer;
let isStandalone=false, managerDecision='pending', managerTab='queue';
let stage='intro', selected=new Set(), result=null, record='', verified=false, analysisTimer, clockTimer, deadline=0, demoId='';
function stopTimers(){clearInterval(introRefreshTimer);clearInterval(clockTimer);clearTimeout(analysisTimer);clearInterval(phraseTimer);}
const stageNames=['intro','read','pick','result','record','analysis','passport','manager','complete'];
function shell(content){const index=stage==='round-feedback'?3:stageNames.indexOf(stage);const chapter=index<4?0:index<7?1:index<8?2:3;main.innerHTML=`<div class="experience"><div class="experience-bar"><span>ALT / ${stage==='manager'?'Manager preview':'Your first shift'}</span><button class="reset" data-action="reset">Start again ↻</button></div><div class="step-track chapter-track" aria-label="Experience chapters">${['01 Challenge','02 Employee','03 Manager','04 Feedback'].map((name,i)=>`<span class="${i<=chapter?'done':''}" ${i===chapter?'aria-current="step"':''}>${name}</span>`).join('')}</div><div class="experience-content"><div class="experience-product-header"><img src="assets/alt-mark-dark.svg" alt="ALT — Align. Learn. Thrive."><span>LEARNING, MADE VISIBLE.</span><b aria-hidden="true">✧</b></div><div class="experience-product-body">${content}</div><div class="experience-product-footer">FROM EXPERIENCE TO EVIDENCE.</div></div></div>`;bindActions();}
function go(next){stopTimers();stage=next;const section=['intro','read','pick','round-feedback','result'].includes(next)?'game':'demo';history.replaceState(null,'','?page='+section);document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===section)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});renderExperience();const heading=main.querySelector('h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'instant'});}
function renderExperience(){document.body.dataset.experienceStage=stage;document.title='Your shift — ALT';
 if(stage==='intro'){shell(`<section class="experience-layout game-intro designed-lobby"><div><p class="eyebrow">01 / THE RESTAURANT CHALLENGE</p><h1>Could you survive<br>the dinner rush?</h1><p class="lead">Catch the order.<br>Keep up with the changes.</p><div class="lobby-rules"><span>${tinyIcon('coffee')}Listen</span><span>${tinyIcon('clock')}Remember</span><span>${tinyIcon('order')}Send</span></div><p class="game-context">Play a simulated shift, then see how ALT turns experience into learning.</p><label class="nickname-label" for="player-name">Your challenge nickname <span>Optional</span></label><input id="player-name" class="nickname-input" maxlength="24" autocomplete="off" placeholder="What should we call you?"><p class="micro lobby-name-note">Public nickname on the leaderboard · Leave blank for Guest.</p>${button('Start my shift','start')}<details class="intro-board"><summary>See the leaderboard ↗</summary><div id="intro-leaderboard">Open to load the latest scores.</div></details><p class="micro">Around 2–3 minutes · No account needed</p></div>${gameLobbyVisual()}</section>`);}
 if(stage==='read'){shell(`<section class="game-card live-service"><div class="round-progress">${rounds.map((r,i)=>`<span class="${i===roundIndex?'current':i<roundIndex?'finished':''}">${i<roundIndex?'✓':i+1}</span>`).join('')}<b>ROUND ${roundIndex+1} / 3</b></div><div class="service-scene"><div class="cafe-backdrop" aria-hidden="true"><span class="pendant p1"></span><span class="pendant p2"></span><span class="cafe-shelf"></span><span class="cafe-table"></span><span class="guest-silhouette"></span></div><div class="guest-ticket"><span class="guest-dot"></span> TABLE ${roundIndex+4}<small>${order.name}</small></div><div class="live-bubble"><p class="eyebrow">YOUR GUEST IS SPEAKING</p><div id="live-phrase" aria-live="polite"></div><div class="phrase-dots" id="phrase-dots">${order.phrases.map(()=>'<i></i>').join('')}</div></div><div class="service-counter"><span>ALT CAFÉ / LIVE SERVICE</span><b>${rushSpeed<1?'RUSH HOUR':'SERVICE PACE'}</b></div></div><p class="micro live-instruction">Each phrase replaces the last. Catch the final order.</p><div class="time-track"><i id="time-fill" style="width:100%"></i></div></section>`);startPhrases();}
 if(stage==='pick'){shell(`<section class="game-card"><div class="topline"><p class="eyebrow" style="margin:0">ROUND ${roundIndex+1} / THE FINAL ORDER</p><span class="countdown" id="clock">${order.pickSeconds} sec</span></div><h1 style="font-size:33px">${roundIndex===0?'What did they order?':'What did they finally choose?'}</h1><p class="micro">Choose one item from each category. Tap again to change your choice.</p><div class="choices">${displayChoices(order).map(c=>`<button class="choice" data-choice="${c.id}" aria-pressed="${selected.has(c.id)}"><span><small>${c.group}</small><b>${c.label}</b></span><span class="check" aria-hidden="true">${selected.has(c.id)?'✓':''}</span></button>`).join('')}</div><div class="time-track"><i id="time-fill" style="width:100%"></i></div><div class="action-row"><span class="micro" id="selection-count">${selected.size} of ${order.correct.length} selected</span>${button('Send order','submit')}</div></section>`);main.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{const c=order.choices.find(x=>x.id===b.dataset.choice);if(selected.has(c.id))selected.delete(c.id);else{order.choices.filter(x=>x.group===c.group).forEach(x=>selected.delete(x.id));selected.add(c.id);}main.querySelectorAll('[data-choice]').forEach(el=>{el.setAttribute('aria-pressed',String(selected.has(el.dataset.choice)));el.querySelector('.check').textContent=selected.has(el.dataset.choice)?'✓':'';});document.querySelector('#selection-count').textContent=`${selected.size} of ${order.correct.length} selected`;}));startClock(order.pickSeconds,'submit');}
 if(stage==='round-feedback'){const last=roundResults.at(-1);shell(`<section class="game-card"><p class="eyebrow">ROUND ${roundIndex+1} / ORDER SENT</p><h1>${last.score===last.total?'You caught every detail.':'A detail slipped through.'}</h1><div class="result-score"><strong>${last.score}<span style="font-size:32px"> / ${last.total}</span></strong><span>details correct this round</span></div><ul class="result-list">${last.details.map(d=>`<li><b>${d.group}</b><span>${d.expected}</span><strong class="${d.correct?'ok':'needs'}">${d.correct?'✓':'Missed'}</strong></li>`).join('')}</ul><p class="experience-note">${roundIndex===0?'Next guest: a change of mind. Keep track of the final choice.':'Last table: a longer order with a late swap. Ready for the rush?'}</p>${button(roundIndex===0?'Next guest':'Take the last table','next-round')}</section>`);}
 if(stage==='result'){shell(`<section class="game-card"><p class="eyebrow">SHIFT COMPLETE / THREE ROUNDS</p><h1>${result.perfect?'Not a detail missed.':result.score>=11?'So close. Good shift.':'That shift had a few twists.'}</h1><div class="result-score"><strong>${result.score}<span style="font-size:32px"> / ${result.total}</span></strong><span>details caught across the shift</span></div><div class="shift-results">${roundResults.map((r,i)=>`<div><span>0${i+1}</span><b>${rounds[i].name}</b><strong>${r.score}/${r.total}</strong></div>`).join('')}</div><p class="shift-highlight">${result.perfect?'THE CLEAN SWEEP':result.score>=11?'THE DETAIL DETECTIVE':'THE COMEBACK SHIFT'}</p><p class="experience-note">${result.perfect?'A clean sweep. Think a friend can match it?':`Your next focus: ${esc(result.focus.toLowerCase())}. Fancy another shift?`}</p><section class="leaderboard-section" aria-label="Shared leaderboard"><p class="eyebrow">THE SHIFT LEADERBOARD / ${rushSpeed<1?'RUSH HOUR':'SERVICE PACE'}</p><h2>How did your shift stack up?</h2><div id="leaderboard-results" aria-live="polite"></div><button class="record-edit" data-action="refresh-board">Refresh leaderboard</button><p class="micro">Correct details first, then total shift time, including pauses between rounds.</p></section><div class="next-chapter"><span>UP NEXT / CHAPTER 02</span><h2>You felt the pressure.<br>Now see how ALT helps.</h2><p>The game simulated a work experience. Next, see it from the employee’s side, then the manager’s.</p>${button('Continue to the ALT demo','record')}<small>Short guided walkthrough · About 30–45 seconds</small></div></section>`);drawLeaderboard();}
 if(stage==='record'){shell(`<section class="game-card"><div class="chapter-heading"><span>02</span><div><p class="eyebrow">THE PRODUCT / EMPLOYEE VIEW</p><h1>Experience becomes<br>a starting point.</h1></div></div><p class="lead">${isStandalone?'Start with a brief shift reflection. Here’s a prepared example.':'Your game stood in for the work. ALT starts here—with a short record of what happened.'}</p><div class="record-label">YOUR SHIFT REFLECTION <span>Prefilled for this demo</span></div><div class="record-box" id="record-copy">${esc(record)}</div><button class="record-edit" data-action="edit">Edit this reflection</button><div class="action-row">${button('See my Passport & next step','analyse')}</div></section>`);}
 if(stage==='analysis'){shell(`<section class="game-card" aria-busy="true"><div class="analysis-orbit"><span aria-hidden="true">↗</span></div><p class="eyebrow">02 / FIND THE LEARNING</p><h1>A moment of work.<br>A clearer next step.</h1><ul class="analysis-items" aria-live="polite"><li class="active" id="analysis-status">Reading your confirmed experience…</li><li>Organising this task’s evidence</li><li>Preparing a next-shift practice task</li></ul><p class="experience-note">Demonstration analysis · Preset rules use your game result. No live AI service is contacted.</p></section>`);analysisTimer=setTimeout(()=>{const status=document.querySelector('#analysis-status');if(status)status.textContent='Your example record and next step are ready.';analysisTimer=setTimeout(()=>go('passport'),1000);},1100);}
 if(stage==='passport'){shell(`<p class="eyebrow">CHAPTER 02 / EMPLOYEE VIEW</p><h1>Skill Passport<span class="gold-question">.</span></h1><p class="lead">Here’s what the employee gets: a learning record and one clear task for the next shift.</p>${passportMarkup(false)}<div class="action-row"><p class="micro">Next: see how a manager reviews the same record.</p>${button('Request manager verification','manager')}</div>`);}
 if(stage==='manager'){shell(`<div class="chapter-heading"><span>03</span><div><p class="eyebrow">THE PRODUCT / MANAGER VIEW</p><h1>A request arrives.<br>A manager takes action.</h1></div></div><div class="request-arrived" role="status"><span>↙</span><div><b>New verification request from ${esc(visitorName())}</b><small>${esc(demoId)} · Sent from the employee Passport</small></div><span class="pill neutral">Awaiting review</span></div><div class="manager-workspace"><nav class="manager-module-nav" aria-label="Manager workspace"><button data-manager-tab="team" aria-pressed="${managerTab==='team'}">This shift’s team</button><button data-manager-tab="queue" aria-pressed="${managerTab==='queue'}">Review queue <b>1</b></button><button data-manager-tab="practice" aria-pressed="${managerTab==='practice'}">Next-shift plan</button></nav><div class="manager-workspace-top"><div><small>MANAGER / RYAN · DEMO</small><h2>${managerTab==='team'?'Who needs support this shift?':managerTab==='queue'?'What’s ready for review?':'Where should support go next?'}</h2></div><span class="manager-live">● Request received</span></div><div class="manager-stats"><div><b>01</b><span>New review request</span></div><div><b>${isStandalone?'1':roundResults.length}</b><span>${isStandalone?'Shift reflection':'Practice rounds'}</span></div><div><b>${result.perfect?'Next level':'Support'}</b><span>${result.perfect?'Ready for another task':'A specific practice focus'}</span></div></div>${managerTab==='team'?teamReadinessMarkup():''}<div class="manager-review-layout" ${managerTab==='team'?'hidden':''}><section class="manager-evidence"><div class="tour-person"><span class="avatar">${esc(visitorInitials())}</span><div><b>${esc(visitorName())}</b><small>Order-taking practice · Evidence for review</small></div></div><h3>${managerTab==='queue'?'The experience behind the request':'The proposed next-shift task'}</h3><div class="record-box">${esc(managerTab==='queue'?record:result.mission)}</div>${!isStandalone&&managerTab==='queue'?`<div class="manager-rounds">${roundResults.map((r,i)=>`<span>${rounds[i].name}<b>${r.score}/${r.total}</b></span>`).join('')}</div>`:''}<div class="support-focus"><span>FOCUS FOR SUPPORT</span><b>${esc(result.focus)}</b><p>${esc(result.mission)}</p></div></section><aside class="manager-decision"><p class="eyebrow">REVIEW & GUIDE</p><h3>Close the loop.</h3><p>Check the record, recognise what was demonstrated, and keep the next practice focused.</p><ul><li>Evidence is visible</li><li>Support needs are clear</li><li>Next task stays practical</li></ul>${button('Confirm record & next step','verify')}<button class="record-edit" data-action="return-practice">Return with practice guidance</button><small>Demo action confirms this activity record, not overall job competence.</small></aside></div></div>`);main.querySelectorAll('[data-manager-tab]').forEach(b=>b.addEventListener('click',()=>{managerTab=b.dataset.managerTab;renderExperience();}));}
 if(stage==='complete'){shell(`<section class="completion feedback-finish"><div class="chapter-heading"><span>04</span><div><p class="eyebrow">YOUR VOICE / OUR NEXT STEP</p><h1>Your feedback.<br>Our next step.</h1></div></div><div class="loop-closed"><span class="done-icon">✓</span><div><b>${verified?'Manager review completed.':'Manager guidance sent.'}</b><p>${esc(visitorName())}’s record ${verified?'now shows manager confirmation.':'now shows that more practice is needed.'} The next-shift task remains visible.</p></div></div><div class="feedback-priority"><p class="eyebrow">YOUR FEEDBACK IS THE REASON WE’RE HERE</p><h2>Would ALT help<br>your team?</h2><p>${isStandalone?'You’ve seen the employee and manager views.':'You’ve tried the challenge and seen both sides of ALT.'} Tell us what felt useful—and what didn’t.</p><a class="btn feedback-cta" href="${formURL}" target="_blank" rel="noopener">Give us your feedback <span>↗</span></a><small>Opens our current feedback & sign-up form. Leave your thoughts in the comments field.</small></div><div class="completion-prompts"><span>Was the idea clear?</span><span>Would it help your team?</span><span>What’s missing?</span></div><div class="finish-secondary"><a href="mailto:hello.alt.team@gmail.com">hello.alt.team@gmail.com</a><button class="reset" data-action="reset">Finish & reset this device ↻</button></div></section>`);}

}
function passportMarkup(done){return `<div class="passport-grid"><section class="passport-card"><p class="eyebrow">YOUR GROWTH, MADE VISIBLE</p><h2 class="passport-heading">Skill Passport<span class="gold-question">.</span></h2><div class="passport-identity"><span class="avatar">${esc(visitorInitials())}</span><div><strong>${esc(visitorName())}</strong><small>${isStandalone?'Demonstration shift record':'This challenge’s learning record'}</small></div></div><div class="skill-tiles"><div class="skill-tile"><span aria-hidden="true">▤</span><b>Order recall</b><small>${isStandalone?'Shift evidence added':result.score+'/'+result.total+' details recalled'}</small></div><div class="skill-tile"><span aria-hidden="true">✧</span><b>Special requests</b><small>${result.requestCorrect?'Detail recalled this time':'Next practice focus'}</small></div></div><div class="skill-line"><div><b>Order-taking practice</b><span class="pill">${isStandalone?'Evidence added':result.score+'/'+result.total+' details'}</span></div><p>${isStandalone?'A work experience captured for review.':'Three simulated rounds captured as practice evidence.'}</p></div><div class="skill-line"><div><b>Activity review</b><span class="pill ${done?'':'neutral'}">${done?'Verified in demo':'Pending manager'}</span></div><p>${done?'The manager preview confirmed this activity record.':'This record has not yet been checked by a manager.'}</p></div><details class="skill-line"><summary style="font-size:12px;cursor:pointer">View my experience record</summary><p>${esc(record)}</p></details></section><section class="mission-card"><p class="eyebrow">TOMORROW / NEXT SHIFT</p><h2>${esc(result.focus)}</h2><div class="mission-task"><small class="pill neutral">To do</small>${esc(result.mission)}</div><p class="micro">A proposed practice task. Not yet completed or verified.</p></section></div>`;}
function teamReadinessMarkup(){const rows=[{name:visitorName(),role:'Front of house · Your demo record',menu:'Not assessed',orders:'Review pending',requests:result.requestCorrect?'Practice recorded':'Needs support',focus:result.focus,current:true},{name:'Mira Chen',role:'New starter · Example colleague',menu:'Practising',orders:'Needs support',requests:'Needs support',focus:'Supported order practice'},{name:'Jamie Lee',role:'Senior team member · Example colleague',menu:'Reviewed',orders:'Reviewed',requests:'Reviewed',focus:'Support new starters'}];return `<section class="team-readiness"><div class="roster-heading"><div><p class="eyebrow">TONIGHT’S SERVICE / SAMPLE ROSTER</p><h3>Your team, at a glance.</h3></div><span class="pill neutral">3 team members</span></div><p class="micro">Sample roster · Review the evidence behind each learning status.</p><p class="matrix-hint">Swipe to see all skills →</p><div class="skill-table-scroll" tabindex="0" aria-label="Scrollable team skill overview"><table class="skill-matrix"><thead><tr><th>Team member</th><th>Menu</th><th>Order taking</th><th>Special requests</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.current?'current-person':''}"><th>${esc(r.name)}<small>${r.role}</small></th>${[r.menu,r.orders,r.requests].map(v=>`<td><span class="skill-status ${v==='Needs support'?'support':v==='Reviewed'?'reviewed':''}">${v}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="roster-next"><div><b>${esc(visitorName())} has sent a verification request.</b><p>Open the record, review the evidence, and guide the next step.</p></div><button class="btn" data-action="open-request">Review ${esc(visitorName())}’s request ↗</button></div></section>`;}
function startStandaloneDemo(){rounds=defaultRounds;isStandalone=true;managerTab='queue';managerDecision='pending';verified=false;roundResults=rounds.map((r,i)=>assessOrder(i===2?r.correct.filter(x=>x!=='tomato'):r.correct,r));result=assessSession(roundResults);record='During today’s shift, I handled orders independently and confirmed a guest’s change of drink. I needed support remembering a special request.';demoId='DEMO-004';go('record');}
function startPhrases(){const start=Date.now();let previous=-2;const duration=order.phrases.reduce((n,p)=>n+p.ms,0)*rushSpeed;const tick=()=>{const elapsed=Date.now()-start,index=phraseAt(elapsed,order,rushSpeed);if(index===-1){stopTimers();go('pick');return;}if(index!==previous){previous=index;const phrase=document.querySelector('#live-phrase');phrase.innerHTML=order.phrases[index].text.split(' ').map((word,i)=>`<span style="animation-delay:${i*28}ms">${esc(word)} </span>`).join('');document.querySelectorAll('#phrase-dots i').forEach((d,i)=>{d.classList.toggle('active',i===index);d.classList.toggle('done',i<index);});}const fill=document.querySelector('#time-fill');if(fill)fill.style.width=`${Math.max(0,1-elapsed/duration)*100}%`;};tick();phraseTimer=setInterval(tick,45);}
function startClock(seconds,next){deadline=Date.now()+seconds*1000;const tick=()=>{const left=Math.max(0,deadline-Date.now());const clock=document.querySelector('#clock'),fill=document.querySelector('#time-fill');if(clock)clock.textContent=`${Math.ceil(left/1000)} sec`;if(fill)fill.style.width=`${left/(seconds*1000)*100}%`;if(left<=0){stopTimers();if(next==='submit')submitOrder();else go(next);}};clockTimer=setInterval(tick,100);tick();}
function submitOrder(){if(stage!=='pick')return;stopTimers();gameAnswers.push([...selected]);roundResults.push(assessOrder([...selected],order));if(roundIndex<rounds.length-1)go('round-feedback');else{result=assessSession(roundResults);record=result.reflection;go('result');sendLeaderboard();}}
function reset(){stopTimers();playerName='';boardToken='';gameAnswers=[];boardResult=null;boardError='';boardBusy=false;rounds=defaultRounds;roundIndex=0;roundResults=[];order=rounds[0];selected=new Set();result=null;record='';verified=false;demoId='ACT-'+Math.random().toString(36).slice(2,6).toUpperCase();go('intro');}
function bindActions(){const boardDetails=main.querySelector('.intro-board');if(boardDetails)boardDetails.addEventListener('toggle',()=>{clearInterval(introRefreshTimer);if(boardDetails.open){loadIntroBoard();introRefreshTimer=setInterval(()=>{if(!document.hidden)loadIntroBoard();},10000);}});main.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.action;if(a==='reset'){if(isStandalone)startStandaloneDemo();else reset();}if(a==='next-round'){roundIndex++;order=rounds[roundIndex];selected=new Set();go('read');}if(a==='start'){startRankedShift();return;}if(a==='refresh-board'){sendLeaderboard();return;}if(a==='pick')go('pick');if(a==='submit')submitOrder();if(a==='record'){history.replaceState(null,'','?page=demo');go('record');}if(a==='edit'){document.querySelector('#record-copy').innerHTML=`<label class="micro" for="reflection-edit">Your reflection</label><textarea id="reflection-edit" maxlength="1200">${esc(record)}</textarea>`;b.hidden=true;document.querySelector('#reflection-edit').focus();}if(a==='analyse'){const edit=document.querySelector('#reflection-edit');if(edit){record=edit.value.trim();if(!record){edit.setCustomValidity('Please keep a short record of this experience.');edit.reportValidity();edit.addEventListener('input',()=>edit.setCustomValidity(''),{once:true});return;}}go('analysis');}if(a==='manager'){managerTab='team';go('manager');}if(a==='open-request'){managerTab='queue';renderExperience();}if(a==='verify'){managerDecision='confirmed';verified=true;go('complete');}if(a==='return-practice'){managerDecision='practice';verified=false;go('complete');}}));}

const boardMode=()=>rushSpeed<1?'rush':'service';
function displayChoices(r){return [...new Set(r.choices.map(c=>c.group))].flatMap(group=>{const list=r.choices.filter(c=>c.group===group);for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]];}return list;});}
async function boardRequest(body){const response=await fetch('/api/leaderboard'+(body?'':'?mode='+boardMode()),{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(9000)});const data=await response.json();if(!response.ok)throw Error(data.error||'Leaderboard unavailable.');return data;}
async function startRankedShift(){
 const start=main.querySelector('[data-action="start"]');if(start.disabled)return;start.disabled=true;start.textContent='Opening your shift…';playerName=normalizeNickname(main.querySelector('#player-name').value);boardError='';boardResult=null;gameAnswers=[];boardToken='';
 try{const data=await boardRequest({action:'start',mode:boardMode()});rounds=questionsForIds(data.questionIds);boardToken=data.token;}catch{rounds=questionsForIds(drawQuestionIds());boardError='The shared leaderboard is unavailable. Your game can still continue.';}
 isStandalone=false;managerTab='queue';managerDecision='pending';roundIndex=0;roundResults=[];order=rounds[0];demoId='ACT-'+Math.random().toString(36).slice(2,6).toUpperCase();selected=new Set();go('read');
}
function boardRows(data){return `<ol class="leaderboard-list">${data.entries.map((e,i)=>`<li class="${e.id===data.mine?.id?'my-score':''}"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(e.name)}</b><strong>${e.score}/${e.total}</strong><small>${(e.ms/1000).toFixed(1)}s</small></li>`).join('')||'<li class="leaderboard-empty">No scores yet. Set the first one.</li>'}</ol>${data.mine?`<div class="your-rank">Your place <b>#${data.mine.rank}</b><span>${esc(data.mine.name)} · ${data.mine.score}/15</span></div>`:''}<p class="micro">${data.local?'Local preview board · Online database not connected.':`${data.total} completed shifts · Shared across devices`}</p>`;}
function drawLeaderboard(){const el=main.querySelector('#leaderboard-results');if(!el)return;el.innerHTML=boardBusy?'<p class="micro">Adding your shift to the board…</p>':boardResult?boardRows(boardResult):`<p class="micro">${esc(boardError||'Loading the leaderboard…')}</p>`;}
async function sendLeaderboard(){if(boardBusy)return;boardBusy=true;drawLeaderboard();try{if(!boardToken)throw Error(boardError||'This shift could not connect to the leaderboard. Please try a new shift.');boardResult=await boardRequest({action:'finish',token:boardToken,name:playerName,mode:boardMode(),answers:gameAnswers});boardError='';}catch(e){boardError=e.message;}finally{boardBusy=false;drawLeaderboard();}}
async function loadIntroBoard(){const target=main.querySelector('#intro-leaderboard');if(!target)return;target.textContent='Loading leaderboard…';const mode=boardMode();try{const data=await boardRequest();if(mode===boardMode()&&target.isConnected)target.innerHTML=boardRows(data);}catch{if(target.isConnected)target.textContent='Leaderboard unavailable right now. You can still play.';}}

function gameQR(){
  const publicSite=!['localhost','127.0.0.1',''].includes(location.hostname);
  if(!publicSite)return '<div class="qr-local"><img class="official-logo" src="assets/alt-mark-light.svg" alt="ALT"><p class="micro">Phone QR activates on the published website.<br>Use the iPad to try this local preview.</p></div>';
  const qr=window.qrcode(0,'M');qr.addData(new URL('?page=game',location.href).href);qr.make();
  return `<img src="${qr.createDataURL(6,24)}" alt="Scan to start the ALT order challenge" width="180" height="180">`;
}
function welcome(){main.innerHTML=`<section class="container team-intro"><p class="eyebrow">YOUR FIRST SHIFT STARTS HERE</p><h1>Can you remember<br>the whole order?</h1><p>Three rounds. Ten details. A few last-minute changes.<br>Play your shift, then follow your result through ALT.</p><div class="actions"><a class="btn" href="?page=game">Play on this iPad ${arrow}</a></div><div class="qr-panel game-card" style="text-align:left;margin-top:40px"><div><h2>Prefer your own phone?</h2><p class="micro" id="qr-message">Scan to play the complete experience on your phone.</p><button class="record-edit" id="copy-link">Copy game link</button></div>${gameQR()}</div></section>`;document.querySelector('#copy-link').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(new URL('?page=game',location.href).href);document.querySelector('#copy-link').textContent='Link copied';}catch{document.querySelector('#qr-message').textContent=new URL('?page=game',location.href).href;}});}
let reelTimer, reelIndex=0, reelPaused=false;
const reelScenes=[()=>`<p class="eyebrow">ALT / FROM EXPERIENCE TO EVIDENCE</p><h1>From Experience<br><span class="brand-accent">to Evidence.</span></h1><p class="lead">Workplace learning for restaurant teams.</p>${productScene()}`,()=>`<p class="eyebrow">THE EVERYDAY CHALLENGE</p><h1>A busy shift.<br>Learning that’s easy to miss.</h1><p class="lead">What went well? Where was support needed?<br>What should happen next?</p>`,()=>`<p class="eyebrow">THE EMPLOYEE’S SIDE</p><h1>Capture the moment.<br>Find the next step.</h1><p class="lead">Experience → Reflection → Skill Passport → Next-shift task</p>${productScene()}`,()=>`<p class="eyebrow">THE MANAGER’S SIDE</p><h1>See the evidence.<br>Support the person.</h1><p class="lead">Review the experience. Guide practice.<br>Keep skill verification in human hands.</p>`,()=>`<p class="eyebrow">TAKE YOUR FIRST SHIFT</p><h1>Three orders.<br>Can you keep up?</h1><p class="lead">Try the challenge on our iPad.<br>Or scan its code to play on your phone.</p><div class="reel-qr">${gameQR()}<div><a class="btn" href="?page=game">Start the challenge ${arrow}</a><p class="micro">Interactive concept demo · Around 2–3 minutes</p></div></div>`];
function reel(){document.body.classList.add('presentation');document.title='ALT — Showcase loop';main.innerHTML=`<section class="reel-stage" id="reel-scene"></section><div class="reel-controls"><button id="reel-pause">Pause</button><button id="reel-fullscreen">Full screen</button><a href="./">Exit</a></div><div class="reel-progress" id="reel-progress"></div>`;const draw=()=>{document.querySelector('#reel-scene').innerHTML=`<span class="reel-step">${String(reelIndex+1).padStart(2,'0')} / 05</span>`+reelScenes[reelIndex]();document.querySelector('#reel-progress').style.width=`${(reelIndex+1)/5*100}%`;};draw();reelTimer=setInterval(()=>{if(!reelPaused){reelIndex=(reelIndex+1)%reelScenes.length;draw();}},6500);document.querySelector('#reel-pause').addEventListener('click',e=>{reelPaused=!reelPaused;e.currentTarget.textContent=reelPaused?'Play':'Pause';});document.querySelector('#reel-fullscreen').addEventListener('click',async e=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch{e.currentTarget.textContent='Use browser full screen';}});}
if(page==='game'){renderExperience();}else if(page==='demo'){startStandaloneDemo();}else if(page==='contact'){contact();document.title='Contact — ALT';}else if(page==='team'){team();document.title='Our team — ALT';}else if(page==='welcome'){welcome();document.title='Start your shift — ALT';}else if(page==='reel'){reel();}else home();
document.querySelector(`[data-nav="${page}"]`)?.setAttribute('aria-current','page');
window.addEventListener('pagehide',()=>{stopTimers();clearInterval(reelTimer);});
window.addEventListener('pageshow',event=>{if(event.persisted){if(page==='game')reset();if(page==='demo')startStandaloneDemo();if(page==='reel')reel();}});

if(['reel','welcome'].includes(page)) document.querySelector('.site-feedback')?.setAttribute('hidden','');
